using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Web.Script.Serialization;

internal static class EnemyDetailsVerification {
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static void V(List<byte> b,uint x){do{byte n=(byte)(x&127);x>>=7;b.Add((byte)(n|(x!=0?128:0)));}while(x!=0);}
    static byte[] Spawn(uint id,float x=93400){var b=new List<byte>{0x41,0x36};V(b,id);b.AddRange(BitConverter.GetBytes((ushort)8196));b.Add(0);b.AddRange(BitConverter.GetBytes(2100146u));b.AddRange(BitConverter.GetBytes((ushort)512));foreach(float f in new[]{x,27000f,26000f,0f})b.AddRange(BitConverter.GetBytes(f));b.AddRange(new byte[3]);V(b,119700);V(b,119700);b.AddRange(new byte[52]);b.AddRange(new byte[]{6,0,1,0});b.AddRange(BitConverter.GetBytes(18));b.AddRange(BitConverter.GetBytes(0x9229f1bcu));b.Add(0);return b.ToArray();}
    static byte[] Select(uint id){var b=new List<byte>{0x34,0x38,0,0,0};V(b,id);return b.ToArray();}
    static byte[] Move(uint id,float x){var b=new List<byte>{0x1c,0x37};V(b,id);b.AddRange(new byte[]{1,0});foreach(float v in new[]{x,27000f,26000f})b.AddRange(BitConverter.GetBytes(v));return b.ToArray();}
    static byte[] GroundCast(uint source,uint target,float x){var b=new List<byte>{2,0x38};V(b,source);b.Add(0);b.AddRange(BitConverter.GetBytes(15210340u));b.AddRange(new byte[]{0,2});V(b,target);b.AddRange(BitConverter.GetBytes(0f));foreach(float f in new[]{x,27000f,26000f})b.AddRange(BitConverter.GetBytes(f));return b.ToArray();}
    static void Feed(EnemyHealthSignal source,byte[] b,double t,string flow="A"){source.Consume(b,0,b.Length,t,flow);}
    internal static void Run(string root){double now=DpsHistory.UtcNow();var source=new EnemyHealthSignal();source.Configure(true);Feed(source,EnemyTargetVerification.Player(10196,"Charlotta",12202,12202,true),now);Feed(source,Spawn(345),now);Feed(source,Select(345),now);var s=source.Read();Check(s!=null&&s.BaseLevel==18&&s.AdjustedLevel==45,"Received base level and user-confirmed level45 display rule");Check(s.Distance.HasValue&&Math.Abs(s.Distance.Value-4)<.001,"Distance from matched received coordinates in centimetres");Check(EnemySpecies.Name(s.Npc,"es")=="Feras","Live verified Zaif type");Feed(source,Move(345,93500),now+.1);s=source.Read();Check(s.Distance.HasValue&&Math.Abs(s.Distance.Value-5)<.001,"Tracked enemy position update");Feed(source,Move(10196,93100),now+.2);Check(Math.Abs(source.Read().Distance.Value-4)<.001,"Own position update");Feed(source,Move(10196,93200),now+.3,"B");Check(Math.Abs(source.Read().Distance.Value-4)<.001,"Other flows cannot change measured distance");Check(EnemyDetailReader.LevelText(45,18,true)=="45 (18)"&&EnemyDetailReader.LevelText(45,18,false)=="45"&&EnemyDetailReader.LevelText(null,18,true)=="— (18)","Adjusted/base labels and unknown display level");EnemyHealthSignal.Sample sample;var frame=Spawn(345);Check(EnemyHealthSignal.Spawn(frame,0,frame.Length,out sample)&&sample.BaseLevel==18,"Complete bounded spawn tail");Check(EnemyHealthSignal.Spawn(frame,0,frame.Length-1,out sample)&&!sample.BaseLevel.HasValue,"Truncated optional metadata cannot falsify level or discard valid HP");EnemyDetailReader.Position a=new EnemyDetailReader.Position{Known=true,X=1,Y=2,Z=3,Time=now-6};Check(!EnemyDetailReader.Distance(a,s.Position,now).HasValue,"Stale local position hides distance");Check(EnemySpecies.Name(2999999,"es")==null,"Unknown types are not inferred from a name");var config=new EnergyConfiguration{Options=new EnergyBarOptions(),Bounds=new Rectangle(0,0,320,4)};var targetBefore=config.EnemyTarget.Copy();ProgressWidgetScale.Apply(config,2,200);Check(config.EnemyHealth.Details.DistanceText.FontSize==28&&config.EnemyHealth.Details.SpeciesText.FontSize==24&&config.EnemyTarget.Details.DistanceText.FontSize==targetBefore.Details.DistanceText.FontSize,"Metadata texts scale with main widget only");var copy=config.Copy();copy.EnemyHealth.Details.DistanceText.Color="#123456";Check(config.EnemyHealth.Details.DistanceText.Color!="#123456","Metadata deep copy");source.Reset();Check(source.Read()==null,"Transport reset clears positions and level");
        VerifyMovementFlags();
        VerifyGroundAimIsolation(now);
        using(var owner=new EnergyOverlay(root,true)){var settings=new HelperSettings(owner);try{settings.VerifyEnemyDetails(root);}finally{settings.Close();}}
        File.WriteAllText(Path.Combine(root,"enemy-details-test.txt"),"PASS: exact bounded base-level tail; full own level/profile; level45/base display; received own/enemy positions and centimetre distance; flow/freshness isolation; skill impact points excluded from player position; out-of-order movement protection; verified species/unknown exclusion; metadata scale/deep copy; independent main-only UI and undo.");}
    internal static void Replay(string root,string frames){var json=new JavaScriptSerializer();int total=0,level=0,poses=0,own=0;var levels=new Dictionary<uint,int>();foreach(var line in File.ReadLines(frames)){var row=json.Deserialize<Dictionary<string,object>>(line);string op=Convert.ToString(row["opcode"]),hex=Convert.ToString(row["hex"]);var b=new byte[hex.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(hex.Substring(i*2,2),16);if(op=="4136"){EnemyHealthSignal.Sample sample;if(EnemyHealthSignal.Spawn(b,0,b.Length,out sample)){total++;if(sample.Position.Known)poses++;if(sample.BaseLevel.HasValue){level++;levels[sample.Npc]=sample.BaseLevel.Value;}}}else if(op=="3336"){int n;EnemyDetailReader.Position p;if(EnemyDetailReader.Character(b,0,b.Length,out n,out p)){Check(n==45,"Recorded own character level corroboration");own++;}}}Check(total>0&&level>0&&poses>0,"Replay requires supported NPC levels and positions");int zaif;Check(levels.TryGetValue(2100146,out zaif)&&zaif==18,"Recorded Zaif base level18");File.WriteAllText(Path.Combine(root,"enemy-details-replay-test.txt"),"PASS: NPC spawns="+total+", bounded base levels="+level+", received spawn positions="+poses+", own level45 profiles="+own+"; captured Zaif base18. Actual position distance needs live UI comparison; no outbound-position guesses.");}
    static void VerifyMovementFlags(){foreach(byte opcode in new byte[]{0x1b,0x1c})foreach(byte flags in new byte[]{0,1,4,5}){var b=new List<byte>{opcode,0x37};V(b,345);b.Add(flags);if((flags&1)!=0)b.Add(0);foreach(float x in new[]{93400f,27000f,26000f})b.AddRange(BitConverter.GetBytes(x));uint actor;EnemyDetailReader.Position position;var bytes=b.ToArray();Check(EnemyDetailReader.Movement(bytes,0,bytes.Length,out actor,out position)&&actor==345&&position.X==93400&&position.Y==27000&&position.Z==26000,"Optional movement byte must follow flag bit0, not a fixed offset");Check(!EnemyDetailReader.Movement(bytes,0,bytes.Length-1,out actor,out position),"Truncated movement position rejected");}uint unknown;EnemyDetailReader.Position missing;Check(!EnemyDetailReader.Movement(null,0,0,out unknown,out missing),"Missing movement envelope rejected");}
    static void VerifyGroundAimIsolation(double now){var source=new EnemyHealthSignal();source.Configure(true);Feed(source,EnemyTargetVerification.Player(10196,"Charlotta",12202,12202,true),now);Feed(source,Spawn(345),now);Feed(source,GroundCast(10196,345,93400),now+.1);Check(source.Read().Actor==345&&Math.Abs(source.Read().Distance.Value-4)<.001,"Target ground coordinates cannot overwrite actual character position or produce false zero");Feed(source,Move(10196,93100),now+.2);Feed(source,Move(10196,93400),now+.15);Check(Math.Abs(source.Read().Distance.Value-3)<.001,"Old character movement cannot replace a newer position");Feed(source,Move(345,93500),now+.3);Feed(source,Move(345,93100),now+.25);Check(Math.Abs(source.Read().Distance.Value-4)<.001,"Old NPC movement cannot replace a newer position");
        source.Reset();Feed(source,EnemyTargetVerification.Player(10196,"Charlotta",12202,12202,true),now-6);Feed(source,Spawn(345),now);Feed(source,GroundCast(10196,345,93400),now);Check(source.Read()!=null&&!source.Read().Distance.HasValue,"Combat aim cannot refresh an expired position or fabricate zero metres");}
}
